using System.Threading.Tasks;

public class OrderService
{
    private readonly IOrderStore _store;
    public OrderService(IOrderStore store) => _store = store;

    // Saves the order; callers await this and expect failures to propagate.
    public async void SaveAsync(Order order)
    {
        await _store.InsertAsync(order);
    }
}

public interface IOrderStore { Task InsertAsync(Order order); }
public record Order(int Id);

