using System.IO;
using System.Xml;

public static class InvoiceParser
{
    // Parses an invoice XML document uploaded by a customer.
    public static XmlDocument Parse(Stream upload)
    {
        var settings = new XmlReaderSettings { DtdProcessing = DtdProcessing.Parse, XmlResolver = new XmlUrlResolver() };
        using var reader = XmlReader.Create(upload, settings);
        var doc = new XmlDocument();
        doc.Load(reader);
        return doc;
    }
}

