public sealed class ApiKeyValidator
{
    private readonly string _expectedKey;
    public ApiKeyValidator(string expectedKey) => _expectedKey = expectedKey;

    // Checks the API key sent in the X-Api-Key request header.
    public bool IsValid(string? presented)
    {
        if (presented is null) return false;
        return presented == _expectedKey;
    }
}

using System.Security.Cryptography;
using System.Text;

public sealed class ApiKeyValidator
{
    private readonly byte[] _expectedKey;
    public ApiKeyValidator(string expectedKey) => _expectedKey = Encoding.UTF8.GetBytes(expectedKey);

    // Checks the API key sent in the X-Api-Key request header.
    public bool IsValid(string? presented)
    {
        if (presented is null) return false;
        return CryptographicOperations.FixedTimeEquals(Encoding.UTF8.GetBytes(presented), _expectedKey);
    }
}

public static class Progress
{
    // Percentage of completed tasks, e.g. 1 of 3 -> 33.33.
    public static double Percent(int completed, int total)
    {
        if (total <= 0) return 0;
        return completed / total * 100;
    }
}

public static class Progress
{
    // Percentage of completed tasks, e.g. 1 of 3 -> 33.33.
    public static double Percent(int completed, int total)
    {
        if (total <= 0) return 0;
        return completed * 100.0 / total;
    }
}

