using System.Collections.Generic;

public sealed class HitCounter
{
    private readonly Dictionary<string, long> _hits = new();

    // Called concurrently from many request threads.
    public void Record(string path)
    {
        _hits[path] = _hits.TryGetValue(path, out var n) ? n + 1 : 1;
    }

    public long Get(string path) => _hits.TryGetValue(path, out var n) ? n : 0;
}

using System.Collections.Concurrent;

public sealed class HitCounter
{
    private readonly ConcurrentDictionary<string, long> _hits = new();

    // Called concurrently from many request threads.
    public void Record(string path)
    {
        _hits.AddOrUpdate(path, 1, (_, n) => n + 1);
    }

    public long Get(string path) => _hits.TryGetValue(path, out var n) ? n : 0;
}
